mapper.select:
SELECT to_char(date_trunc(#{truncUnit}, tm),

            'YYYY-MM-DD HH24:MI:SS'
            'YYYY-MM-DD'
        ) AS "bucket",
       AVG(${metricColumn}) AS "value"
FROM rms_metric_log
WHERE instance_id = #{instanceId}
  AND tm BETWEEN #{startTime} AND #{endTime}
GROUP BY date_trunc(#{truncUnit}, tm)
ORDER BY date_trunc(#{truncUnit}, tm)

SELECT CASE WHEN COUNT(*) = 0 THEN 100
            ELSE ROUND(100.0 * COUNT(CASE WHEN collect_status = '1' THEN 1 END) / COUNT(*), 2)
       END
FROM rms_node_status_log
WHERE instance_id = #{instanceId}
  AND tm BETWEEN #{startTime} AND #{endTime}
